# Check: does mirroring work with different rules for 0 vs non-0 specials?
test_grid = [
    [0, 0, 9, 9],      # only 0s in left → all→0
    [6, 9, 9, 9],      # has non-0 (6) in left → mirror with bg→2  
    [6, 9, 9, 6],      # has non-0 (6) in left → mirror with bg→2
    [9, 9, 9, 9],      # no specials → ?
    [9, 6, 9, 0],      # mixed in right half, 6 in left → ?
    [9, 9, 9, 9],      # no specials
    [6, 9, 6, 9],      # has 6 in both halves
    [9, 6, 6, 9]       # 6 only in right half
]

print("Left half rule determines fill:")
for row in test_grid:
    left = row[:2]
    left_has_0 = 0 in left
    left_has_nonzero = any(v != 0 and v != 9 for v in left)

    output = []
    for c in range(4):
        if c < 2:
            if left[c] == 9:
                output.append(0 if left_has_0 else 2)
            else:
                output.append(left[c])
        else:
            if left[1-c] == 9:
                output.append(0 if left_has_0 else 2)
            else:
                output.append(left[1-c])

    print(f"{row} -> {output}")

